   1: // 节奏拳纯逻辑层。动作识别只依赖相邻加速度向量的变化。
   2: 
   3: const GAME_MS = 30000;
   4: const HIT_WINDOW_MS = 350;
   5: 
   6: function finite(value) {
   7:   return typeof value === 'number' && Number.isFinite(value);
   8: }
   9: 
  10: function validSample(sample) {
  11:   return sample && finite(sample.x) && finite(sample.y) && finite(sample.z);
  12: }
  13: 
  14: function vectorDelta(previous, current) {
  15:   const dx = current.x - previous.x;
  16:   const dy = current.y - previous.y;
  17:   const dz = current.z - previous.z;
  18:   return Math.sqrt(dx * dx + dy * dy + dz * dz);
  19: }
  20: 
  21: function createPunchDetector(options) {
  22:   const config = options || {};
  23:   const threshold = finite(config.threshold) ? config.threshold : 4.5;
  24:   const cooldownMs = finite(config.cooldownMs) ? config.cooldownMs : 350;
  25:   let previous = null;
  26:   let lastPunchAt = -Infinity;
  27: 
  28:   return {
  29:     push(sample, timestamp) {
  30:       if (!validSample(sample) || !finite(timestamp)) return false;
  31:       if (!previous) {
  32:         previous = sample;
  33:         return false;
  34:       }
  35:       const movement = vectorDelta(previous, sample);
  36:       previous = sample;
  37:       if (movement < threshold || timestamp - lastPunchAt < cooldownMs) return false;
  38:       lastPunchAt = timestamp;
  39:       return true;
  40:     },
  41:   };
  42: }
  43: 
  44: function scorePunch(punchAt, beatAt) {
  45:   const difference = Math.abs(punchAt - beatAt);
  46:   if (difference <= 120) return { points: 100, grade: 'perfect' };
  47:   if (difference <= 250) return { points: 70, grade: 'good' };
  48:   if (difference <= HIT_WINDOW_MS) return { points: 40, grade: 'hit' };
  49:   return { points: 0, grade: 'miss' };
  50: }
  51: 
  52: function beatIntervalForHeartRate(heartRate) {
  53:   if (!finite(heartRate) || heartRate < 120) return 1000;
  54:   if (heartRate < 150) return 1200;
  55:   return 1400;
  56: }
  57: 
  58: function motionClassAt(mode, elapsedMs) {
  59:   const elapsed = Math.max(0, finite(elapsedMs) ? elapsedMs : 0);
  60:   if (mode === 'cue') {
  61:     if (elapsed < 90) return 'motion-windup';
  62:     if (elapsed < 220) return 'motion-strike';
  63:     if (elapsed < HIT_WINDOW_MS) return 'motion-recover';
  64:   } else if (mode === 'hit') {
  65:     if (elapsed < 140) return 'motion-impact';
  66:     if (elapsed < 360) return 'motion-recover';
  67:   } else if (mode === 'miss') {
  68:     if (elapsed < 140) return 'motion-recoil';
  69:     if (elapsed < 360) return 'motion-recover';
  70:   }
  71:   return 'motion-guard';
  72: }
  73: 
  74: function createStats() {
  75:   return { score: 0, hits: 0, targets: 0, streak: 0, maxStreak: 0 };
  76: }
  77: 
  78: function recordHit(stats, points) {
  79:   const current = stats || createStats();
  80:   const streak = current.streak + 1;
  81:   return {
  82:     score: current.score + points,
  83:     hits: current.hits + 1,
  84:     targets: current.targets + 1,
  85:     streak,
  86:     maxStreak: Math.max(current.maxStreak, streak),
  87:   };
  88: }
  89: 
  90: function recordMiss(stats) {
  91:   const current = stats || createStats();
  92:   return {
  93:     score: current.score,
  94:     hits: current.hits,
  95:     targets: current.targets + 1,
  96:     streak: 0,
  97:     maxStreak: current.maxStreak,
  98:   };
  99: }
 100: 
 101: module.exports = {
 102:   GAME_MS,
 103:   HIT_WINDOW_MS,
 104:   createPunchDetector,
 105:   scorePunch,
 106:   beatIntervalForHeartRate,
 107:   motionClassAt,
 108:   createStats,
 109:   recordHit,
 110:   recordMiss,
 111: };
